  static void Materials(){plaster=Mat("Cold plaster");concrete=Mat("Service concrete");wood=Mat("Museum oak");oldWood=Mat("Old timber");metal=Mat("Patinated metal");stone=Mat("Carved limestone");brass=Mat("Aged brass");glass=Mat("Display glass");bulb=Mat("Aged diffuser");text=Mat("World typography");}
  static Material Mat(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Mats+"/"+name+".mat");
  static Material NightMat(string name,Color color){string path=Root+"/Materials/Night01 "+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);EditorUtility.SetDirty(m);return m;}
  static GameObject Box(string name,Vector3 p,Vector3 s,Material m,bool collider=false){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(generated);go.transform.position=p;go.transform.localScale=s;go.GetComponent<Renderer>().sharedMaterial=m;if(!collider)UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());return go;}
  static void FloorStrip(string name,Vector3 p,Vector3 s)=>Box(name,p,s,concrete,false);
  static void MakeRoom(RoomSpec r){
   Vector3 c=new(r.center.x,0,r.center.y);Box(r.name+" floor",c+Vector3.up*.012f,new Vector3(r.size.x,.024f,r.size.y),r.service?concrete:wood);Box(r.name+" ceiling",c+Vector3.up*4.2f,new Vector3(r.size.x,.25f,r.size.y),plaster);
   Wall(r.name+" north",c+Vector3.forward*r.size.y*.5f,r.size.x,0,r.service,r.north);Wall(r.name+" south",c-Vector3.forward*r.size.y*.5f,r.size.x,0,r.service,r.south);Wall(r.name+" east",c+Vector3.right*r.size.x*.5f,r.size.y,90,r.service,r.east);Wall(r.name+" west",c-Vector3.right*r.size.x*.5f,r.size.y,90,r.service,r.west);
   Sign(RoomNames[r.name],c+new Vector3(0,3.5f,-r.size.y*.5f+.16f),Quaternion.Euler(0,180,0),.04f);Sign(RoomNames[r.name],c+new Vector3(0,3.5f,-r.size.y*.5f-.16f),Quaternion.identity,.04f);
   for(float x=-r.size.x*.35f;x<=r.size.x*.35f;x+=Mathf.Max(4,r.size.x*.35f))Box("Ceiling beam",c+new Vector3(x,4,0),new Vector3(.2f,.25f,r.size.y*.92f),r.service?metal:oldWood);
   Furnish(r,c);
   if(r.id==7){foreach(float x in new[]{-3f,3f}){var p=c+new Vector3(x,2.3f,r.size.y*.48f-.08f);Box("Canvas artwork",p,new Vector3(1.65f,1.65f,.025f),NightMat("Ochre canvas",new Color(.34f,.19f,.075f)));Lamp(r.id,p+new Vector3(0,1.3f,-2),p,3,new Color(1,.72f,.4f),false);}}
   if(r.id==8){foreach(float x in new[]{-3f,3f}){var statue=GameObject.CreatePrimitive(PrimitiveType.Capsule);statue.name="Gallery B sculpture";statue.transform.SetParent(generated);statue.transform.position=c+new Vector3(x,1.5f,2);statue.transform.localScale=new Vector3(.5f,.6f,.4f);statue.GetComponent<Renderer>().sharedMaterial=stone;UnityEngine.Object.DestroyImmediate(statue.GetComponent<Collider>());}}
   if(r.id==3)for(int i=-1;i<=1;i++){Box("Security monitor screen",c+new Vector3(i*.85f,1.35f,1.94f),new Vector3(.68f,.42f,.025f),NightMat("Monitor glass",new Color(.09f,.3f,.32f)));Sign("0"+(i+1),c+new Vector3(i*.85f,1.35f,1.92f),Quaternion.identity,.02f);}
   if(r.id==10){Box("Archive wood panel",c+new Vector3(0,1.7f,6.8f),new Vector3(11,3.4f,.15f),oldWood);}
  }
  static void Wall(string name,Vector3 center,float length,float yaw,bool service,bool opening){var root=new GameObject(name);root.transform.SetParent(generated);root.transform.position=center;var q=Quaternion.Euler(0,yaw,0);if(!opening){var solid=Box("Solid wall",center+Vector3.up*2,new Vector3(length,4,.25f),service?concrete:plaster,true);solid.transform.rotation=q;solid.transform.SetParent(root.transform,true);return;}float side=(length-3)/2;foreach(float sign in new[]{-1f,1f}){var p=Box("Room wall",center+Vector3.up*2+q*Vector3.right*sign*(1.5f+side*.5f),new Vector3(side,4,.25f),service?concrete:plaster,true);p.transform.rotation=q;p.transform.SetParent(root.transform,true);}var lintel=Box("Door lintel",center+Vector3.up*3.5f,new Vector3(3,1,.25f),service?metal:oldWood,true);lintel.transform.rotation=q;lintel.transform.SetParent(root.transform,true);}
  static void Furnish(RoomSpec r,Vector3 c){
   if(r.name.Contains("MAIN")){foreach(float x in new[]{-7f,7f})foreach(float z in new[]{-7f,7f})Column(c+new Vector3(x,0,z));Bench(c+new Vector3(-6,0,0),90);Bench(c+new Vector3(6,0,0),90);}
   if(r.name.Contains("GALLERY")){for(int i=-1;i<=1;i+=2){Box("Gallery pedestal",c+new Vector3(i*3,.45f,2),new Vector3(1.3f,.9f,1.3f),stone,true);Box("Collection frame",c+new Vector3(i*3,2.3f,r.size.y*.48f),new Vector3(2,2,.12f),oldWood);}}
   if(r.name=="STORAGE"){for(int row=0;row<3;row++)for(int side=-1;side<=1;side+=2){var p=c+new Vector3(side*4,0,-4+row*4);var rack=NightMat("Rack steel",new Color(.25f,.28f,.3f));foreach(float y in new[]{.15f,1.15f,2.15f})Box("Rack shelf",p+Vector3.up*y,new Vector3(1,.12f,2.5f),rack,true);foreach(float x in new[]{-.45f,.45f})foreach(float z in new[]{-1.2f,1.2f})Box("Rack upright",p+new Vector3(x,1.2f,z),new Vector3(.1f,2.4f,.1f),rack,true);}}
   if(r.name.Contains("ANCIENT")){for(int i=-1;i<=1;i++){Box("Stone sarcophagus",c+new Vector3(i*4,.55f,1),new Vector3(2.3f,1.1f,1.1f),stone,true);Box("Carved sarcophagus lid",c+new Vector3(i*4,1.16f,1),new Vector3(2.1f,.18f,.95f),brass);}}
   if(r.name=="ELECTRICAL"){for(int i=-1;i<=1;i++)Box("Breaker cabinet",c+new Vector3(i*2.4f,1.6f,3.7f),new Vector3(1.6f,2.4f,.35f),metal,true);}
   if(r.name=="SECURITY"){Box("Security desk",c+new Vector3(0,.55f,2.8f),new Vector3(5,1.1f,1.2f),metal,true);}
   if(r.name.Contains("LOADING")){for(int i=0;i<2;i++)Box("Loading dock bumper",c+new Vector3(-5+i*10,.5f,3.8f),new Vector3(2,1,.5f),metal,true);}
   if(r.name=="SERVICE CORRIDOR"){for(int i=-3;i<=3;i++)Box("Service pipe",c+new Vector3(i*2.2f,3.25f,2.8f),new Vector3(1.6f,.12f,.12f),metal);}
   if(r.name=="STAFF ROOM"){var board=NetworkBox("Task board",c+new Vector3(-3,2.2f,4.72f),new Vector3(4,1.7f,.12f),oldWood);board.AddComponent<NightInteractable>().mode=NightInteraction.ShiftBoard;Sign("НОЧЬ 01\nПРИЁМКА · УЧЁТ · ОХРАНА",c+new Vector3(-3,2.2f,4.62f),Quaternion.identity,.034f);Box("Radio equipment",c+new Vector3(3.8f,.7f,2.8f),new Vector3(1.8f,1.4f,.8f),metal,true);}
  }
  static void Column(Vector3 p){Box("Hall column",p+Vector3.up*2,new Vector3(.65f,4,.65f),stone,true);Box("Column capital",p+Vector3.up*3.9f,new Vector3(.9f,.2f,.9f),stone);}
  static void Bench(Vector3 p,float yaw){var q=Quaternion.Euler(0,yaw,0);var seat=Box("Museum bench",p+Vector3.up*.5f,new Vector3(2.2f,.16f,.55f),oldWood,true);seat.transform.rotation=q;}
  static GameObject Sign(string label,Vector3 p,Quaternion q,float size){var go=new GameObject(label);go.transform.SetParent(generated);go.transform.SetPositionAndRotation(p,q);var tm=go.AddComponent<TextMesh>();tm.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");tm.text=label;tm.fontSize=64;tm.characterSize=size;tm.anchor=TextAnchor.MiddleCenter;tm.alignment=TextAlignment.Center;tm.color=new Color(.48f,.45f,.38f);go.GetComponent<Renderer>().sharedMaterial=text;go.AddComponent<DepthText>().template=text;return go;}
