  static void RoomLamp(RoomSpec r){Vector3 c=new(r.center.x,3.85f,r.center.y);Color color=r.id==0||r.id==7?new Color(1,.72f,.45f):r.name.Contains("ANCIENT")?new Color(.82f,.62f,.42f):new Color(.62f,.7f,.78f);float main=r.name=="STAFF ROOM"?9:r.name=="STORAGE"?5.5f:7;Lamp(r.id,c,c-Vector3.up*3.4f,main,color,r.id==6||r.id==7||r.id==8);if(r.id!=6)Lamp(r.id,c+Vector3.forward*r.size.y*.22f,c+new Vector3(0,-2,r.size.y*.48f),3,color,false);if(Mathf.Max(r.size.x,r.size.y)>=16){Vector3 axis=r.size.x>=r.size.y?Vector3.right*r.size.x*.28f:Vector3.forward*r.size.y*.28f;Lamp(r.id,c+axis,(c+axis)-Vector3.up*3.3f,5.5f,color,false);Lamp(r.id,c-axis,(c-axis)-Vector3.up*3.3f,5.5f,color,false);}if(r.name=="STORAGE")Lamp(r.id,c+new Vector3(3,0,-3),c+new Vector3(3,-3,-3),3.5f,color,false);if(r.service&&r.id!=0)Lamp(r.id,c+new Vector3(r.size.x*.3f,-.5f,r.size.y*.3f),c+new Vector3(r.size.x*.3f,-3,r.size.y*.3f),1.5f,new Color(.55f,.04f,.025f),false,true);}
