  static bool RoomContains(string roomName,Vector3 point,float margin=.15f){var room=Rooms.FirstOrDefault(r=>r.name==roomName);return room.name!=null&&Mathf.Abs(point.x-room.center.x)<=room.size.x*.5f-margin&&Mathf.Abs(point.z-room.center.y)<=room.size.y*.5f-margin;}
  static void ValidateObjectiveAccess(List<string> errors,NightObjectiveZone zone,NightPhase activationPhase,string expectedRoom){
   if(!zone){errors.Add("Missing objective destination for "+expectedRoom);return;}
   if(!RoomContains(expectedRoom,zone.transform.position))errors.Add($"{zone.name} is outside its expected reachable room {expectedRoom}");
   if(!zone.DependencyAllowsPhase((int)activationPhase))errors.Add($"{zone.name} activates in {activationPhase} before its access dependency unlocks");
   if(zone.accessDoor&&(zone.requiredUnlockPhase<zone.accessDoor.unlockPhase||!zone.waypoint))errors.Add($"{zone.name} has an invalid door dependency or world marker");
  }
  [MenuItem("Tools/Do Not Touch/Run Night 01 Validation")]
  public static void Validate(){var errors=new List<string>();var d=UnityEngine.Object.FindFirstObjectByType<NightShiftDirector>();if(SceneManager.GetActiveScene().path!=Path)errors.Add("Open DoNotTouch_Night01 before Night 01 validation");if(!d)errors.Add("NightShiftDirector missing");if(Rooms.Any(r=>!GameObject.Find(r.name+" floor")))errors.Add("One or more required rooms missing");if(Rooms.Any(r=>!GameObject.Find(r.name+" ceiling")))errors.Add("One or more room ceilings missing");for(int i=0;i<Rooms.Length;i++)for(int j=i+1;j<Rooms.Length;j++){RoomSpec a=Rooms[i];RoomSpec b=Rooms[j];float overlapX=Mathf.Min(a.center.x+a.size.x*.5f,b.center.x+b.size.x*.5f)-Mathf.Max(a.center.x-a.size.x*.5f,b.center.x-b.size.x*.5f);float overlapZ=Mathf.Min(a.center.y+a.size.y*.5f,b.center.y+b.size.y*.5f)-Mathf.Max(a.center.y-a.size.y*.5f,b.center.y-b.size.y*.5f);if(overlapX>.05f&&overlapZ>.05f)errors.Add("Overlapping room geometry: "+a.name+" / "+b.name);}if(UnityEngine.Object.FindObjectsByType<Watcher>(FindObjectsSortMode.None).FirstOrDefault() is not Watcher w||w.positions.Length<10)errors.Add("Watcher navigation anchors incomplete");if(UnityEngine.Object.FindObjectsByType<NightInteractable>(FindObjectsSortMode.None).Count(i=>i.mode==NightInteraction.FusePickup)<3)errors.Add("Three fuse locations required");if(!AssetDatabase.LoadAssetAtPath<ExhibitRegistry>(Root+"/ScriptableObjects/Night01Registry.asset"))errors.Add("Scanner registry missing");if(!d||!d.restrictedDoor||!d.restrictedDoor.Locked.Value)errors.Add("Restricted door missing or unlocked");if(UnityEngine.Object.FindObjectsByType<SecurityCameraNode>(FindObjectsSortMode.None).Length<5)errors.Add("Five security cameras required");if(!UnityEngine.Object.FindFirstObjectByType<MuseumCart>())errors.Add("Museum cart missing");if(!UnityEngine.Object.FindObjectsByType<PickupObject>(FindObjectsSortMode.None).Any(p=>p.heavy))errors.Add("Heavy exhibit missing");if(!UnityEngine.Object.FindFirstObjectByType<InventoryScanner>())errors.Add("Inventory scanner missing");if(!UnityEngine.Object.FindFirstObjectByType<ShiftManager>().exitZone)errors.Add("Staff exit missing");if(d&&(d.shipmentZones.Length!=6||d.placementZones.Length!=3||!d.sculptureZone||!d.archiveReturnZone||!d.finalReturnZone))errors.Add("Objective chain references incomplete");
   foreach(var room in Rooms){foreach(var side in new[]{"north","south","east","west"}){var wall=GameObject.Find(room.name+" "+side);if(!wall||wall.GetComponentsInChildren<Collider>().Length==0)errors.Add(room.name+" missing wall "+side);}if(!UnityEngine.Object.FindObjectsByType<TextMesh>(FindObjectsSortMode.None).Any(t=>t.text==RoomNames[room.name]))errors.Add("Missing Russian room sign: "+room.name);}
   foreach(var door in UnityEngine.Object.FindObjectsByType<MuseumDoor>(FindObjectsSortMode.None)){bool opening=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Any(t=>t.name=="Door lintel"&&Vector3.Distance(t.position,door.transform.position+Vector3.up*3.5f)<.1f);if(!opening)errors.Add("Door without wall opening: "+door.name);}
   var identities=UnityEngine.Object.FindObjectsByType<ExhibitIdentity>(FindObjectsSortMode.None);var zones=UnityEngine.Object.FindObjectsByType<NightObjectiveZone>(FindObjectsSortMode.None);
   if(identities.Select(i=>i.exhibitId).Distinct().Count()!=identities.Length)errors.Add("Duplicate objective prop ID");
   foreach(var identity in identities){if(string.IsNullOrEmpty(identity.exhibitId)||!identity.GetComponentsInChildren<TextMesh>().Any(t=>t.text.Contains(identity.exhibitId)))errors.Add("Indistinguishable object ID: "+identity.name);if(!zones.Any(z=>z.Accepts(identity.GetComponent<PickupObject>())))errors.Add("Missing destination: "+identity.exhibitId);}
   var objectiveCrates=identities.Where(i=>i.destinationId=="crate_a"||i.destinationId=="crate_b").ToArray();var shipmentZones=d?d.shipmentZones:Array.Empty<NightObjectiveZone>();
   if(objectiveCrates.Length!=6||objectiveCrates.Any(i=>!i.GetComponentsInChildren<TextMesh>().Any(t=>t.text.Contains(i.exhibitId)&&t.text.Contains(ExhibitIdentity.Destination(i.destinationId).ToUpperInvariant()))))errors.Add("Every objective crate needs a large ID and destination label");
   if(shipmentZones.Any(z=>string.IsNullOrEmpty(z.expectedExhibitId)||!z.plaque||!z.plaque.text.Contains(z.expectedExhibitId)||!z.waypoint||!z.waypoint.target||z.waypoint.roomSize.x<=0))errors.Add("Shipment destination ID or room waypoint missing");
   foreach(var crate in objectiveCrates)if(shipmentZones.Count(z=>z.expectedExhibitId==crate.exhibitId&&z.Accepts(crate.GetComponent<PickupObject>()))!=1)errors.Add("Objective crate must have exactly one matching destination: "+crate.exhibitId);
   if(d){foreach(var zone in d.shipmentZones)ValidateObjectiveAccess(errors,zone,NightPhase.NormalShift,zone.requiredKind=="crate_a"?"GALLERY A":"GALLERY B");if(d.placementZones.Length==3){ValidateObjectiveAccess(errors,d.placementZones.FirstOrDefault(z=>z.requiredKind=="placement_a"),NightPhase.NormalShift,"GALLERY A");ValidateObjectiveAccess(errors,d.placementZones.FirstOrDefault(z=>z.requiredKind=="placement_b"),NightPhase.NormalShift,"ANCIENT WING");ValidateObjectiveAccess(errors,d.placementZones.FirstOrDefault(z=>z.requiredKind=="placement_c"),NightPhase.NormalShift,"MAIN HALL");}ValidateObjectiveAccess(errors,d.sculptureZone,NightPhase.WatcherActive,"GALLERY B");ValidateObjectiveAccess(errors,d.archiveReturnZone,NightPhase.RestrictedArea,"ARCHIVE / RESTRICTED");ValidateObjectiveAccess(errors,d.finalReturnZone,NightPhase.FinalTask,"LOADING / RECEIVING");if(d.archiveReturnZone&&(d.archiveReturnZone.accessDoor!=d.restrictedDoor||d.archiveReturnZone.requiredUnlockPhase!=(int)NightPhase.RestrictedArea||d.restrictedDoor.unlockPhase!=(int)NightPhase.RestrictedArea))errors.Add("Archive objective access dependency is incomplete");}
   if(d&&d.CurrentShipmentZone()&&string.IsNullOrEmpty(d.CurrentShipmentZone().label))errors.Add("Current objective has no destination");
   var playerPrefab=UnityEngine.Object.FindFirstObjectByType<NetworkManager>()?.NetworkConfig.PlayerPrefab;var player=playerPrefab?playerPrefab.GetComponent<PlayerController>():null;if(!player||!player.flashlight)errors.Add("Player flashlight missing");
   if(NightRules.StateForPhase(NightPhase.FirstAnomalies)!=WatcherState.Awake)errors.Add("Watcher cannot leave Dormant");
   if(d&&!d.ObjectiveText(UnityEngine.Object.FindFirstObjectByType<ShiftManager>()).Contains("ТЕКУЩАЯ ЗАДАЧА"))errors.Add("Missing Russian objective");
   PrototypeBuilder.Validate();if(errors.Count>0){foreach(var e in errors)Debug.LogError("NIGHT 01: "+e);throw new InvalidOperationException("Night 01 validation failed: "+errors.Count);}Debug.Log("NIGHT 01 VALIDATION PASSED: walls, door openings, unique IDs, reachable destinations, access dependencies, Russian signs, Watcher phases and references.");}
  public static void BuildMac(){Build();var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Path},locationPathName="Builds/macOS/DoNotTouch_Night01.app",target=BuildTarget.StandaloneOSX,options=BuildOptions.Development});if(report.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Night 01 macOS build failed");}
